/**
 * The recorded confirmation of a no-typing corrective action.
 *
 * The *interaction* changed, not the authority: an authorised person still has to activate a
 * clearly labelled button in a red warning panel that names the record and its consequences, and
 * the server still requires an explicit confirmation flag before the first mutation.
 *
 * Because no phrase and no free-text reason are collected any more, the audit row must not imply
 * that somebody wrote one. It records the confirmation *source* and a description generated by the
 * application, and it keeps a user-supplied note only when one was actually supplied.
 */

/** The only confirmation source these actions record. */
export const CONFIRMATION_SOURCE_BUTTON = 'BUTTON' as const;

export type CorrectiveAction = 'REMOVE' | 'RESTORE' | 'REOPEN' | 'PURGE';

const DESCRIPTIONS: Record<CorrectiveAction, string> = {
  REMOVE:
    'Recoverable removal confirmed with the in-application confirmation button (no typed phrase and no free-text reason were collected)',
  RESTORE:
    'Restoration confirmed with the in-application confirmation button (no typed phrase and no free-text reason were collected)',
  REOPEN:
    'Correction of a recorded completion confirmed with the in-application confirmation button (no typed phrase and no free-text reason were collected)',
  PURGE:
    'Permanent erasure confirmed with the in-application confirmation button (no typed phrase and no free-text reason were collected)'
};

/** The application-generated description an audit row records for one confirmed action. */
export function systemConfirmationDescription(action: CorrectiveAction): string {
  return DESCRIPTIONS[action];
}

/**
 * The audit fragment shared by every no-typing corrective action.
 *
 * `note` is the text a person actually entered, when the interface offered an optional note. It is
 * never derived from the confirmation itself, and it stays absent (`null`) when nobody wrote one.
 */
export function confirmationRecord(
  action: CorrectiveAction,
  note?: string | null
): {
  confirmationSource: typeof CONFIRMATION_SOURCE_BUTTON;
  confirmationDescription: string;
  userNote: string | null;
} {
  const value = String(note ?? '').trim();
  return {
    confirmationSource: CONFIRMATION_SOURCE_BUTTON,
    confirmationDescription: systemConfirmationDescription(action),
    userNote: value ? value : null
  };
}
